// What the parts on the bench physically are, imported from the modelled assets.
//
// The counterpart to `boardProfiles.ts`: a board knows its own size and render,
// and now so does every other part. Generated by `scripts/assets/import-part-assets.py`
// from each asset's `part.json`, where `dimensionsMm` is verified against a
// datasheet or fabrication print rather than estimated.
//
// This exists because the app was guessing. It declared the MAX98357A at
// 17.8 x 13.2 mm against a real 17.78 x 25.4, and derived a ring's diameter as
// `N x 10 mm / pi`, which gives 25.5 mm for an 8-LED ring that measures 32.2 and
// 191 mm for a 60 that measures 158. The hardware view's whole promise is that a
// part is the size it is beside your board, so a remembered number is not a
// small inaccuracy — it is the view lying about the bench.

import { PART_CATALOGUE_DATA } from '../generated/partCatalogueData'
import type { RenderIndicator } from '../boards/boardCapabilities'
import { validatePartManifest, type ManifestOrigin, type PartManifest } from './manifest/partManifest'
import type { SupplyRail } from './manifest/vocabulary'

/** One pad's point on the part's render, in render pixels from the top-left. */
export interface PartPad {
  /** The pad's silkscreen, matching the same position in `pinLabelsLeftToRight`. */
  label: string
  xPx: number
  yPx: number
}

export type PartCategory =
  | 'microphone' | 'amplifier' | 'storage' | 'led-output'
  | 'input-control' | 'audio-source' | 'support' | 'display' | 'switching-power' | 'power-monitor' | 'power-conversion'
  | 'communication'
  | 'battery'

export interface PartRenderAsset {
  /** Path relative to the site root, e.g. `parts/max98357a-i2s-amplifier.webp`. */
  file: string
  widthPx: number
  heightPx: number
  /** Density the render actually achieved — below the 12 px/mm target for parts
   *  over ~100 mm, where the 1200 px cap wins. */
  pxPerMm?: number
  /** The part's indicator LEDs on this render, in its own pixels. */
  indicators?: RenderIndicator[]
}

/** The pixel geometry an LED output's asset was built for. */
export interface PartLedLayout {
  form: 'strip' | 'matrix' | 'ring' | 'hub75'
  count?: number
  width?: number
  height?: number
  diameterMm?: number
  /** Centre-to-centre LED spacing. 4 mm for a P4 HUB75 panel, 10 mm for a
   *  WS2812B matrix, 16.7 mm for a 60 LEDs/m strip. */
  pitchMm?: number
}

/**
 * The driver contract an auxiliary display's asset declares.
 *
 * Imported rather than hand-declared, for the same reason `dimensionsMm` is:
 * the app used to carry these numbers from memory and got them wrong. A
 * resolution typed into the app is a resolution that can disagree with the
 * panel on the bench, and every fixed layout is computed from it.
 */
export interface PartDisplaySpec {
  /** Exact controller, e.g. `SSD1306`, `ST7789`, `TM1637`. */
  controller: string
  /** Panel size in pixels. A 7-segment module reports digits x segments. */
  resolutionPx: [number, number]
  /** How the board talks to it, e.g. `I2C`, `SPI`, `CLK + DIO`. */
  interface: string
  /** Touch controller when one is fitted, else null. */
  touchController: string | null
  /**
   * How touch is read when there is no controller to name.
   *
   * `resistive-shared` is a bare sheet wired across four lines the LCD bus
   * already owns. It has no digitiser, so `touchController` is honestly null -
   * and a panel that asked only that question read this board as having no
   * touch at all and never emitted its read.
   */
  touchSurface?: 'resistive-shared' | null
  /**
   * Where the lit pixels sit on the part's render, as `[x, y, width, height]`
   * in render pixels from the top-left. One rectangle for a bitmap panel (its
   * active area), one per digit package for a segment module. Projected from
   * the model, so the bench draws a panel's output on its glass rather than
   * guessing at the bezel. Absent when the screen does not face the camera.
   */
  screensPx?: Array<[number, number, number, number]>
}

/** Electrical identity carried by an imported relay-module asset. */
export interface PartRelaySpec {
  channels: number
  coilVoltage: string
  trigger: 'active-low' | 'active-high' | string
  contacts: string
  contactRating: string
  optoIsolated: boolean
  /** What the output can switch. A phototriac is AC only; a dry contact is both. */
  loadKind: 'ac' | 'dc' | 'ac-dc'
  /** Current the load still sees while the channel is off. */
  leakage: string
  /** How the logic side is separated from the load, in the datasheet's terms. */
  isolation: string
  /** True when the device switches only at a mains zero, so it cannot be dimmed. */
  zeroCross?: boolean
  /** Smallest load current the device is specified to hold. */
  minimumLoad?: string
  /** Silkscreen name of each channel input, in channel order. */
  channelInputLabels?: string[]
}

/** Electrical identity carried by an imported DC MOSFET switch module. */
export interface PartMosfetSpec {
  channels: number
  device: string
  trigger: 'active-high' | 'active-low' | string
  /** The load-side supply the module switches, e.g. "6-28 V DC". */
  loadSupply: string
  continuousCurrent: string
  optoIsolated: boolean
  /** Whether the board carries its own flyback diode across the load. */
  flybackDiode: boolean
  /** What the board prints beside each channel, one per channel (A to D on the Mosfetti). */
  channelLabels?: string[]
  /**
   * What each channel's input terminal prints, when that is not the channel's
   * own name: the YYNMOS-4's channel 1 is wired at PWM1. Absent when the
   * channel label is also the input's (the Mosfetti's A).
   */
  channelInputLabels?: string[]
  /** Load-side terminals as printed, left to right in the render. */
  loadTerminals?: string[]
  /** PWM frequency to dim the load at; absent on a module that only switches. */
  pwmHz?: number
}

/** Request contract carried by an imported USB-C PD trigger module. */
export interface PartPdTriggerSpec {
  protocols: string
  /** The fixed voltages the module can ask a charger for. */
  selectableVoltagesV: number[]
  defaultVoltageV: number
  maxCurrentA: number
  maxPowerW: number
  /** How the voltage is chosen on the board. */
  selection: string
}

/** Switching contract carried by an imported low-side driver array (ULN2803A). */
export interface PartDriverChipSpec {
  device: string
  package: string
  channels: number
  outputType: string
  /** The input level that turns a channel on. */
  inputActiveLevel: 'high' | 'low'
  maxOutputVoltageV: number
  maxChannelCurrentMa: number
  /** Package pin names in pin-number order. */
  pinout: string[]
}

/** Output contract carried by an imported I2C PWM driver. */
export interface PartPwmDriverSpec {
  device: string
  interface: string
  channels: number
  resolutionBits: number
  /** Every address the board's straps can select, as numbers. */
  i2cAddresses: number[]
  defaultI2cAddress: number
  /** The chip's internal oscillator, the base of its PWM frequency. */
  oscillatorMHz: number
  minPwmHz: number
  maxPwmHz: number
  defaultPwmHz: number
}

/** Drive contract carried by an imported buzzer module. */
export interface PartBuzzerSpec {
  type: 'active' | 'passive'
  /** The pin level that sounds it. */
  activeLevel: 'high' | 'low'
  /**
   * The pitch the transducer is loudest at: an active buzzer's only pitch, a
   * passive one's best. Null when the source gives none.
   */
  resonanceKHz: number | null
  soundLevel: string
  /** What it draws from its pin or supply while sounding. */
  maxCurrentMa: number
}

/** What a microSD module may be fed, carried by every SPI card socket. */
export interface PartSdCardSpec {
  /** The rail its power pad takes. */
  supplyVolts: number
  /** False for a bare socket: 5 V power or 5 V SPI can destroy the card. */
  levelShifted: boolean
}

/** A battery-backed real-time clock on the I2C bus. */
export interface PartRtcSpec {
  /** Selects the register driver the firmware carries. */
  device: string
  /** The address that driver reads. */
  i2cAddress: number
}

/** A UART-controlled audio player's electrical and timing contract. */
export interface PartUartPlayerSpec {
  /** Selects the command protocol the firmware carries. */
  device: string
  supplyMinV: number
  supplyMaxV: number
  /** The draw with its speaker amplifier driving a load. */
  maxCurrentMa: number
  baud: number
  /** The module ignores a command that follows another sooner than this. */
  commandGapMs: number
  /** How long after power-up before it takes its first command. */
  bootMs: number
}

/** An RS-485 transceiver that receives DMX512. */
export interface PartRs485Spec {
  device: string
  supplyVolts: number
  /** The level the receive output swings to; above 3.6 V it needs a divider. */
  rxLogicVolts: number
  terminationFitted: boolean
  /** The board's designator for the fitted terminator, when it prints one. */
  terminationRef?: string
}

/** A DIN-5 MIDI receiver on a UART RX pin. */
export interface PartMidiDinSpec {
  device: string
  supplyVolts: number
  /** An optocoupler separates the cable from the controller. */
  isolated: boolean
  /** Which socket of the board is MIDI IN. */
  inputSocket: 'left' | 'right'
}

/** Drive and feedback contract carried by a four-wire PWM fan. */
export interface PartFanSpec {
  supplyVoltageV: number
  maxCurrentA: number
  maxRpm: number
  minRpmAt20Percent: number
  pwmHz: number
  tachPulsesPerRevolution: number
  tachOutput: string
}

/** Measuring contract carried by an imported current/voltage monitor. */
export interface PartPowerMonitorSpec {
  device: string
  interface: string
  /** Every address the board's straps can select, as numbers. */
  i2cAddresses: number[]
  defaultI2cAddress: number
  /** The fitted shunt; firmware divides the shunt voltage by it. */
  shuntOhms: number
  busVoltageMaxV: number
  currentMaxA: number
  senseSide: 'high-side' | 'low-side' | string
}

/** Reporting contract carried by an imported radar presence sensor. */
export interface PartPresenceSensorSpec {
  device: string
  interface: string
  /** The rate the module streams its frames at; firmware opens the UART at it. */
  baud: number
  /** Width of one distance gate. */
  gateMeters: number
  /** The factory range, which the preview's distance slider spans. */
  maxRangeMeters: number
}

/** Electrical contract carried by a digital capacitive-touch module. */
export interface PartTouchSensorSpec {
  device: string
  interface: string
  activeLevel: 'high' | 'low'
  mode: string
  supplyMinV: number
  supplyMaxV: number
  responseMinMs: number
  responseMaxMs: number
}

/** Measuring contract carried by an ambient-light sensor breakout. */
export interface PartLightSensorSpec {
  device: string
  interface: string
  i2cAddresses: number[]
  defaultI2cAddress: number
  /** Upper end of the ordinary high-resolution measurement range. */
  maxLux: number
}

/** Measuring contract carried by a temperature / humidity / pressure sensor. */
export interface PartEnvironmentSensorSpec {
  device: string
  interface: string
  i2cAddresses: number[]
  defaultI2cAddress: number
  temperatureMinC: number
  temperatureMaxC: number
  humidityMinPercent: number
  humidityMaxPercent: number
  pressureMinHpa: number
  pressureMaxHpa: number
}

/** Measuring contract carried by a six-axis accelerometer and gyroscope. */
export interface PartMotionVectorSpec {
  device: string
  interface: string
  i2cAddresses: number[]
  defaultI2cAddress: number
  /** Accelerometer full scale, in g. */
  accelRangeG: number
  /** Gyroscope full scale, in degrees per second. */
  gyroRangeDps: number
}

/** Contract carried by a multi-electrode capacitive-touch controller. */
export interface PartTouchPadSpec {
  device: string
  interface: string
  electrodes: number
  i2cAddresses: number[]
  defaultI2cAddress: number
  /** Factory-sensible counts below baseline that count as a touch, and as a release. */
  touchThreshold: number
  releaseThreshold: number
}

/** Contract carried by a two-axis analog joystick with a push switch. */
export interface PartJoystickSpec {
  device: string
  interface: string
  /** The resistance of each axis potentiometer, in ohms. */
  axisPotOhms: number
  /** Which level SW reads when the stick is pushed. */
  switchActive: 'low' | 'high'
}

/** Contract carried by a quadrature rotary encoder. */
export interface PartEncoderSpec {
  device: string
  /** Full quadrature cycles per turn; each is four A/B transitions. */
  pulsesPerRevolution: number
  /** Clicks per turn. */
  detents: number
  /** Which level SW reads when the shaft is pushed. */
  switchActive: 'low' | 'high'
  /** False for a bare encoder, whose contacts float without the controller's pull-ups. */
  onboardPullUps: boolean
}

/** Measuring contract carried by a pulse-ranging distance sensor. */
export interface PartDistanceSensorSpec {
  device: string
  interface: string
  minMm: number
  maxMm: number
  /** The width of the trigger pulse a pulse-ranging module needs, in microseconds. */
  triggerPulseUs?: number
  /** The level the Echo pin swings to, in volts. */
  echoVolts?: number
  /** Every address an I2C module answers on; absent on a pulse-ranging one. */
  i2cAddresses?: number[]
  defaultI2cAddress?: number
}

/** Measuring contract carried by a 1-Wire temperature probe. */
export interface PartTemperatureSensorSpec {
  device: string
  interface: string
  temperatureMinC: number
  temperatureMaxC: number
  /** The DATA-to-VDD pull-up the bare probe needs, in ohms. */
  pullUpOhms: number
}

/**
 * Contract carried by a one-pin digital sensor: a switch, or a module whose
 * output is a plain high or low (reed, Hall, tilt, vibration, float and limit
 * switches, IR break-beam, door contacts). The node's behaviour is fixed in
 * code; everything that differs between parts is here.
 */
export interface PartDigitalSensorSpec {
  /** The level the pin reads while the sensor is actuated. */
  activeLevel: 'high' | 'low'
  /**
   * What holds the line at its idle level: `internal` is the controller's
   * pull-up (the sketch enables it), `external` a resistor on the module or
   * the user's wiring, `none` a module that drives the line both ways.
   */
  pullUp: 'none' | 'internal' | 'external'
  /** Milliseconds a reading must hold before it counts; 0 for a clean output. */
  debounceMs: number
  /** What the part is powered from, when it takes a supply. */
  supplyVolts?: number
  /** Short copy for the preview toggle while actuated ("Magnet near"). */
  activeLabel: string
  /** Short copy for the preview toggle while idle ("Magnet away"). */
  idleLabel: string
}

/**
 * Contract carried by a one-pin motion sensor (a PIR or a microwave radar
 * module). The node's behaviour is fixed in code; the sense of its output and
 * what it is powered from are here.
 */
export interface PartMotionSensorSpec {
  /** The level OUT reads while the module sees movement. */
  activeLevel: 'high' | 'low'
  /** How long OUT stays at the active level after the last movement, when the module fixes it. */
  holdSeconds?: number
  /** What the module's supply pad is powered from. */
  supplyVolts: number
}

/**
 * Contract carried by a passive switch-matrix keypad: the geometry the scan
 * reads and what each key is printed with. A keypad has no supply or ground.
 */
export interface PartKeypadSpec {
  rows: number
  columns: number
  /** What each key is printed with, row by row; `rows * columns` entries. */
  legends: string[]
  /** The pad printed for each row, top to bottom. */
  rowLabels: string[]
  /** The pad printed for each column, left to right. */
  columnLabels: string[]
}

/** Contract carried by a demodulating IR receiver module. */
export interface PartIrReceiverSpec {
  /** What the module's supply pad is powered from; 4.5 V and over needs a divided signal into the logic input. */
  supplyVolts: number
  /** The carrier the demodulator is tuned to. */
  carrierKHz?: number
}

/** One point of a calibration curve: the pin voltage, and what it means. */
export interface PartCalibrationPoint {
  volts: number
  value: number
}

/**
 * Contract carried by a one-pin analog sensor (soil moisture, force-sensitive
 * resistor, flex, slide pot, gas, water level). The reading leaves the node in
 * the part's real unit, through a calibration curve.
 */
export interface PartAnalogSensorSpec {
  /** Short unit label for readouts and copy ("%", "N", "ppm"). */
  unit: string
  /** The supply the module is meant to run from. */
  supplyVolts: number
  /** The pin voltage that reads 0 and the one that reads full scale. */
  adcRange: { minVolts: number; maxVolts: number }
  /** At least two points, strictly rising in volts, and monotonic in value. */
  curve: PartCalibrationPoint[]
  /** The reading is held inside this window, whatever the curve says. */
  outputMin: number
  outputMax: number
  /** Decimal places a readout shows; defaults to two. */
  decimals?: number
}

/** Network contract carried by a wired-Ethernet controller module. */
export interface PartEthernetSpec {
  /** The controller chip, which picks the firmware's PHY driver. */
  controller: string
  interface: string
  /** The controller's SPI clock ceiling. */
  maxSpiClockMHz: number
  link: string
}

/** Physical contract for a matched long-range pixel-data TX/RX pair. */
export interface PartPixelDataExtenderSpec {
  mode: string
  maxDistanceMeters: number
  maxDataRateMbps: number
  supplyMinV: number
  supplyMaxV: number
  /** The conductors between the two modules, in the manufacturer's order. */
  pairConductors: string[]
}

export type ConverterPadsMm = Record<'IN+' | 'IN-' | 'OUT+' | 'OUT-', [number, number]>

/** A DC-DC converter between a 12/24 V source and a 5 V load. */
export interface PartPowerConverterSpec {
  /** `controller` powers only the controller and 5 V peripherals; `led-rail` is the LED supply. */
  role: 'controller' | 'led-rail'
  /** Every job the module may be given, when more than one; `role` is the one a new converter takes. */
  roles?: Array<'controller' | 'led-rail'>
  topology: string
  inputMinV: number
  inputMaxV: number
  /** How far the input must stay above the output (a buck's dropout). */
  minHeadroomV: number
  outputSetV: number
  continuousCurrentMa: number
  peakCurrentMa: number
  /** Used to size the source side conservatively. */
  typicalEfficiency: number
  /** An isolated converter's output negative must be bonded to the common ground. */
  isolated: boolean
  /** Adjustable output: it ships at an arbitrary voltage and must be set before use. */
  adjustable: boolean
  /**
   * Whether the module holds its own output current. `adjustable`: a CC/CV
   * module with a current setting. `fixed`: a stated limit at its rating
   * (overload protection, a buck's switch current limit). `none`: no output
   * limit, such as a plain boost, which limits only its switch and cannot stop
   * an output short. Only a limited module can make the wiring smaller than
   * the LEDs' full-white draw.
   */
  outputCurrentLimit: 'adjustable' | 'fixed' | 'none'
  /** Printed terminal names in physical order. */
  terminals: string[]
  /** Terminal centres as [x, y] ratios within the uncropped render, aligned with `terminals`. */
  terminalPositions?: Array<[number, number]>
  /** Output current against ambient, as [C, percent] in rising order; absent means none. */
  deratingCurve?: Array<[number, number]>
}

export type CellChemistry = 'li-ion' | 'lifepo4'

export interface PartBatteryCellSpec {
  chemistry: CellChemistry
  formFactor: string
  nominalV: number
  chargeV: number
  dischargeCutoffV: number
  capacityMah: number
  maxContinuousDischargeMa: number
  maxChargeMa: number
  internalResistanceMohm: number
  internalResistanceBasis: 'ac-1khz' | 'dc'
  chargeTempC: [number, number]
  dischargeTempC: [number, number]
}

export interface PartBatteryModuleSpec {
  series: number
  chemistries: CellChemistry[]
  protection?: {
    continuousDischargeMa: number
    continuousChargeMa: number
    overchargeV: number
    overDischargeV: number
    port: 'common' | 'separate'
    switchedLine: 'negative' | 'positive'
    temperatureSensor: boolean
    powerTerminals: string[]
  }
  balance?: {
    type: 'active' | 'passive'
    balanceMa: number
    standbyMa?: number
    balanceTerminals: string[]
    connectionOrder?: string[]
  }
  charger?: {
    device: string
    chargeVPerCell: number
    maxChargeMa: number
    inputMaxW: number
    inputProtocols: string
    bidirectional: boolean
    batteryTerminals: [string, string]
  }
  output?: {
    topology: 'boost' | 'buck'
    outputV: number
    continuousMa: number
    typicalEfficiency: number
    terminals: string[]
    usbOutput: boolean
  }
}

/**
 * An I2S MEMS microphone's capture contract. FastLED's `fl::audio::Config`
 * factory and `MicProfile` are a FastLED API tied to the part's silicon, so the
 * part names them; a chip FastLED ships neither for names `captureAdapter`
 * instead, which is the app's own receive code (it stays in code, selected by
 * this field).
 */
export interface PartMicrophoneSpec {
  /** Exact chip, e.g. `INMP441`; matched against the type's `devices`. */
  device: string
  /** `fl::audio::Config` factory the ESP32 backend calls. */
  fastledFactory?: 'CreateInmp441' | 'CreateIcs43434' | 'CreateGenericMEMS'
  /** `fl::audio::MicProfile` member the Teensy backend is handed. */
  fastledProfile?: 'INMP441' | 'ICS43434' | 'GenericMEMS'
  /** The app's own capture adapter, for a chip FastLED's driver cannot read. */
  captureAdapter?: 'sph0645-classic-esp32'
}

/** A stereo line-level ADC read over I2S. */
export interface PartLineInputSpec {
  /** Exact chip, e.g. `PCM1802`; matched against the type's `devices`. */
  device: string
  /** Analog channels the part digitises. */
  channels: number
}

/** An I2S audio stage on the board's own pins: a DAC or a speaker amplifier. */
export interface PartI2sAudioSpec {
  /** Exact chip, e.g. `MAX98357A`; matched against the type's `devices`. */
  device: string
  /**
   * What comes out of it. A DAC's line out is what a power amplifier expects; an
   * amplifier's bridge-tied speaker output is not line level.
   */
  output: 'speaker' | 'line'
}

/** An analog power amplifier: line level in, speakers out. */
export interface PartPowerAmpSpec {
  /** The amplifier chip, descriptive; no code branches on it. */
  device: string
  /** The supply the board needs, in volts. */
  supplyVolts: number
  channels: number
  inputKind: 'line'
}

export interface PartCatalogueEntry {
  partId: string
  label: string
  category?: PartCategory | string
  manufacturer?: string
  logicVoltage?: string
  /** Real size, datasheet-verified. The render's own axes: width across, height
   *  down, with the pin header along the bottom edge. */
  dimensionsMm: { width: number; height: number }
  pinLabelsLeftToRight?: string[]
  notes?: string[]
  ledLayout?: PartLedLayout
  /** Present exactly on switching-power relay modules. */
  relay?: PartRelaySpec
  /** Present exactly on DC MOSFET switch modules. */
  mosfet?: PartMosfetSpec
  /** Present exactly on USB-C PD trigger modules. */
  pdTrigger?: PartPdTriggerSpec
  /** Present exactly on low-side driver arrays. */
  driverChip?: PartDriverChipSpec
  /** Present exactly on I2C PWM driver modules. */
  pwmDriver?: PartPwmDriverSpec
  /** Present exactly on buzzer modules. */
  buzzer?: PartBuzzerSpec
  /** Present exactly on four-wire PWM fans. */
  fan?: PartFanSpec
  /** Present exactly on current/voltage monitor modules. */
  powerMonitor?: PartPowerMonitorSpec
  /** Present exactly on radar presence sensors. */
  presenceSensor?: PartPresenceSensorSpec
  /** Present exactly on digital capacitive-touch sensors. */
  touchSensor?: PartTouchSensorSpec
  /** Present exactly on calibrated digital ambient-light sensors. */
  lightSensor?: PartLightSensorSpec
  /** Present exactly on calibrated temperature / humidity / pressure sensors. */
  environmentSensor?: PartEnvironmentSensorSpec
  /** Present exactly on six-axis accelerometer and gyroscope modules. */
  motionVectorSensor?: PartMotionVectorSpec
  /** Present exactly on multi-electrode capacitive-touch controller modules. */
  touchPad?: PartTouchPadSpec
  /** Present exactly on analog joystick modules. */
  joystick?: PartJoystickSpec
  /** Present exactly on catalogued rotary encoders. */
  encoder?: PartEncoderSpec
  /** Present exactly on pulse-ranging distance sensors. */
  distanceSensor?: PartDistanceSensorSpec
  /** Present exactly on 1-Wire temperature probes. */
  temperatureSensor?: PartTemperatureSensorSpec
  /** Present exactly on one-pin digital sensors (switches and plain high/low modules). */
  digitalSensor?: PartDigitalSensorSpec
  /** Present exactly on one-pin analog sensors read through a calibration curve. */
  analogSensor?: PartAnalogSensorSpec
  /** Present exactly on one-pin PIR and microwave motion modules. */
  motionSensor?: PartMotionSensorSpec
  /** Present exactly on passive switch-matrix keypads. */
  keypad?: PartKeypadSpec
  /** Present exactly on demodulating IR receiver modules. */
  irReceiver?: PartIrReceiverSpec
  /**
   * Where each catalogued pad sits on the render, in the render's own pixels,
   * in `pinLabelsLeftToRight` order. The Build Diagram draws wires to these;
   * a part without them is drawn with a centred header.
   */
  pads?: PartPad[]
  /** Drilled-hole radius in render pixels (a pad is coloured at this size); 4 when absent. */
  padHoleRadiusPx?: number
  /** The controller rail the supply pad takes, or `none` when it takes no supply. */
  supplyRail?: SupplyRail
  /** The pad printing the supply, when the usual supply names would pick the wrong one. */
  powerPadLabel?: string
  /**
   * A DC-DC converter's four wire pads, measured from its drawing, in
   * millimetres from the render's top-left board corner. Present only where the
   * pads sit at the board corners (the stub drawing then sends positive up and
   * negative down); absent, the Build Diagram reads the block's `terminalPositions`.
   */
  converterPadsMm?: ConverterPadsMm
  /** Present exactly on wired-Ethernet controller modules. */
  ethernet?: PartEthernetSpec
  /** Present exactly on a matched differential pixel-data extender pair. */
  pixelDataExtender?: PartPixelDataExtenderSpec
  /** Present exactly on DC-DC converter modules. */
  powerConverter?: PartPowerConverterSpec
  /** Present exactly on individual battery cells. */
  batteryCell?: PartBatteryCellSpec
  /** Present exactly on protection, balance, charger and pack-output boards. */
  batteryModule?: PartBatteryModuleSpec
  /** Present exactly on microSD card modules. */
  sdCard?: PartSdCardSpec
  /** Present exactly on real-time clock modules. */
  rtc?: PartRtcSpec
  /** Present exactly on UART audio player modules. */
  uartPlayer?: PartUartPlayerSpec
  /** Present exactly on RS-485 DMX transceiver modules. */
  rs485?: PartRs485Spec
  /** Present exactly on DIN MIDI interface boards. */
  midiDin?: PartMidiDinSpec
  /** Present exactly on the auxiliary-display parts. */
  display?: PartDisplaySpec
  /** Present exactly on I2S MEMS microphones. */
  microphone?: PartMicrophoneSpec
  /** Present exactly on I2S line-level ADC boards. */
  lineInput?: PartLineInputSpec
  /** Present exactly on I2S DACs and speaker amplifiers. */
  i2sAudio?: PartI2sAudioSpec
  /** Present exactly on analog power amplifiers. */
  powerAmp?: PartPowerAmpSpec
  render?: PartRenderAsset
}

/*
 * The catalogue is a runtime registry. It starts as the bundled parts, in the
 * generated file's order, and can gain parts later: a save's embedded
 * manifests, or a package from the signed index. Every reader goes through
 * `PART_CATALOGUE` or `partById`, so an added part is seen by all of them the
 * moment it is registered.
 *
 * What a reader must do about that:
 *   - never cache a value derived from the catalogue at module load. Read it
 *     when asked, or memoise it with `memoByCatalogue`, which recomputes when
 *     the catalogue version moves;
 *   - in React, call `usePartCatalogueVersion()` (./usePartCatalogueVersion)
 *     in any component that reads the catalogue outside a hook that already
 *     depends on the graph, so it renders again when a part arrives.
 *
 * Bundled parts are never replaced, so a value derived only from a bundled id
 * (a node's default part, say) cannot go stale and needs none of this.
 */
export type PartOrigin = ManifestOrigin

const BUNDLED_PART_IDS: ReadonlySet<string> = new Set(Object.keys(PART_CATALOGUE_DATA))

interface RegisteredPart {
  manifest: PartManifest
  origin: PartOrigin
  /** Node type ids this app can use the part for, in the manifest's order. */
  usableTypes: readonly string[]
}

const registeredParts = new Map<string, RegisteredPart>()
const catalogueListeners = new Set<() => void>()
let catalogueRevision = 0

const catalogueEntries: Record<string, PartCatalogueEntry> = { ...PART_CATALOGUE_DATA }

/**
 * Every part, bundled first. A write through this object (a test adding a
 * fixture part, say) moves the version like `registerParts` does, so a value
 * memoised by version can never go stale behind it. `registerParts` is the way
 * to add a real part: it validates, and it records where the part came from.
 */
export const PART_CATALOGUE: Record<string, PartCatalogueEntry> = new Proxy(catalogueEntries, {
  set(target, key, value) {
    const written = Reflect.set(target, key, value)
    catalogueChanged()
    return written
  },
  deleteProperty(target, key) {
    const had = Object.prototype.hasOwnProperty.call(target, key)
    const deleted = Reflect.deleteProperty(target, key)
    if (had) catalogueChanged()
    return deleted
  },
})

export type PartRegistrationStatus =
  /** A new part joined the catalogue. */
  | 'added'
  /** A higher revision of a registered part replaced the earlier one. */
  | 'replaced'
  /** The same revision is already registered. */
  | 'unchanged'
  /** A bundled part has this id (or the registered one is bundled): it is never replaced. */
  | 'kept-bundled'
  /** A registered part of a higher revision has this id. */
  | 'kept-newer'
  | 'needs-newer-app'
  | 'invalid'

export interface PartRegistration {
  partId: string | null
  status: PartRegistrationStatus
  /** Why a part was not added; empty for `added`, `replaced` and `unchanged`. */
  reasons: string[]
}

/** Moves whenever the set of parts, or any registered part, changes. Starts at 0. */
export function catalogueVersion(): number {
  return catalogueRevision
}

/** Call `listener` after every catalogue change. Returns the unsubscribe. */
export function subscribeCatalogue(listener: () => void): () => void {
  catalogueListeners.add(listener)
  return () => { catalogueListeners.delete(listener) }
}

function catalogueChanged(): void {
  catalogueRevision += 1
  for (const listener of [...catalogueListeners]) listener()
}

/**
 * Memoise a value derived from the catalogue. The returned reader recomputes
 * only when the catalogue version has moved, so its result is also referentially
 * stable between changes (safe as a React dependency).
 */
export function memoByCatalogue<T>(compute: () => T): () => T {
  let at = -1
  let value: T
  return () => {
    if (at !== catalogueRevision) {
      value = compute()
      at = catalogueRevision
    }
    return value
  }
}

/**
 * Add parts to the catalogue.
 *
 * Every manifest goes through `validatePartManifest` for `origin`; only an `ok`
 * one is added, and the rest are reported, never thrown. A registered part
 * never replaces a bundled one. A later revision replaces an earlier one with
 * the same id only when both are downloaded: a downloaded part never takes the
 * place of one registered as bundled. Listeners fire once per call that
 * changed anything.
 *
 * Nothing here fetches. Callers (a save's embedded parts, the signed index)
 * hand in what they already hold.
 */
export function registerParts(manifests: readonly unknown[], origin: PartOrigin): PartRegistration[] {
  let changed = false
  const results = manifests.map((candidate): PartRegistration => {
    const checked = validatePartManifest(candidate, origin)
    if (checked.status === 'invalid') return { partId: checked.partId, status: 'invalid', reasons: checked.errors }
    if (checked.status === 'needs-newer-app') {
      return { partId: checked.partId, status: 'needs-newer-app', reasons: checked.reasons }
    }
    const { manifest } = checked
    const id = manifest.partId
    if (BUNDLED_PART_IDS.has(id)) {
      return { partId: id, status: 'kept-bundled', reasons: ['a bundled part has this id and is never replaced'] }
    }
    const existing = registeredParts.get(id)
    let status: PartRegistrationStatus = 'added'
    if (existing) {
      if (existing.origin === 'bundled' && origin !== 'bundled') {
        return { partId: id, status: 'kept-bundled', reasons: ['a bundled part has this id and is never replaced'] }
      }
      if (manifest.revision === existing.manifest.revision) return { partId: id, status: 'unchanged', reasons: [] }
      if (manifest.revision < existing.manifest.revision) {
        return { partId: id, status: 'kept-newer', reasons: [`revision ${existing.manifest.revision} is already registered`] }
      }
      status = 'replaced'
    }
    // A manifest is JSON by contract; a copy keeps the caller from editing the catalogue.
    const stored = JSON.parse(JSON.stringify(manifest)) as PartManifest
    registeredParts.set(id, { manifest: stored, origin, usableTypes: checked.usableTypes.map((type) => type.nodeType) })
    catalogueEntries[id] = stored
    changed = true
    return { partId: id, status, reasons: [] }
  })
  if (changed) catalogueChanged()
  return results
}

/** Where a part came from, or undefined for an id the catalogue does not hold. */
export function partOrigin(partId: string): PartOrigin | undefined {
  if (BUNDLED_PART_IDS.has(partId)) return 'bundled'
  return registeredParts.get(partId)?.origin
}

/** Registered (non-bundled-data) parts the app can use for `nodeType`, in registration order. */
export function registeredPartsForType(nodeType: string): PartManifest[] {
  const parts: PartManifest[] = []
  for (const entry of registeredParts.values()) {
    if (entry.usableTypes.includes(nodeType)) parts.push(entry.manifest)
  }
  return parts
}

/**
 * Bundled parts written for `nodeType`, in the type's menu order: those with a
 * `copy.optionOrder` first by that number, then the rest in catalogue order.
 * The first is the type's default module. Bundled parts never change, so this
 * is safe to read at module load; downloaded parts are `registeredPartsForType`
 * and always follow these.
 */
export function bundledPartsForType(nodeType: string): PartManifest[] {
  const parts = Object.values(PART_CATALOGUE_DATA)
    .filter((manifest) => manifest.partTypes?.includes(nodeType))
  return parts
    .map((manifest, index) => ({ manifest, index }))
    .sort((a, b) =>
      (a.manifest.copy?.optionOrder ?? Number.POSITIVE_INFINITY) - (b.manifest.copy?.optionOrder ?? Number.POSITIVE_INFINITY)
      || a.index - b.index)
    .map(({ manifest }) => manifest)
}

/**
 * The size of a bundled part. A bundled part always has one, so a missing part
 * is a coding error here, not a value to substitute: callers that meet a part
 * of unknown origin read `dimensionsMm` from its own entry instead.
 */
export function bundledPartDimensionsMm(partId: string): { width: number; height: number } {
  const entry = PART_CATALOGUE_DATA[partId]
  if (!entry) throw new Error(`No bundled part ${partId}`)
  return entry.dimensionsMm
}

/** The node types a registered part can be used for; empty for any other id. */
export function registeredPartTypes(partId: string): readonly string[] {
  return registeredParts.get(partId)?.usableTypes ?? []
}

/** Every registered part, in registration order. */
export function registeredPartManifests(): PartManifest[] {
  return [...registeredParts.values()].map((entry) => entry.manifest)
}

/**
 * Remove a downloaded part from the catalogue. A bundled part, or an id the
 * catalogue does not hold, is left alone. The caller decides whether the part
 * is still in use; nodes that name it become held nodes at once.
 */
export function unregisterPart(partId: string): boolean {
  const entry = registeredParts.get(partId)
  if (!entry || entry.origin !== 'downloaded' || BUNDLED_PART_IDS.has(partId)) return false
  registeredParts.delete(partId)
  delete catalogueEntries[partId]
  downloadedRenders.delete(partId)
  catalogueChanged()
  return true
}

/** Test only: drop every registered part, back to the bundled catalogue. */
export function resetRegisteredPartsForTests(): void {
  downloadedRenders.clear()
  if (registeredParts.size === 0) return
  for (const id of registeredParts.keys()) delete catalogueEntries[id]
  registeredParts.clear()
  catalogueChanged()
}

export function partById(partId: string): PartCatalogueEntry | undefined {
  return PART_CATALOGUE[partId]
}

/*
 * A graph property names an electrical role; a module prints the name its
 * manufacturer chose for that role. For example, the square ST7789 breakout
 * prints SCL/SDA/RST/BL for SPI SCK/MOSI/reset/backlight. Keep the aliases here
 * beside the catalogue boundary so every physical view can show the words a
 * person will actually find on the part.
 */
const PART_PIN_PROPERTY_ALIASES: Record<string, readonly string[]> = {
  clkPin: ['CLK', 'SCK', 'SCL'],
  dioPin: ['DIO', 'DATA', 'DIN'],
  dinPin: ['DIN', 'DATA', 'DIO'],
  // WIZnet prints the W5500's active-low lines with a trailing n.
  csPin: ['CS', 'LOAD', 'LCD_CS', 'SCNN'],
  // A parallel board silkscreens register-select as RS; it is the same signal
  // an SPI board prints DC, so one property carries both names.
  dcPin: ['DC', 'RS', 'LCD_RS'],
  resetPin: ['RST', 'RESET', 'RES', 'LCD_RST', 'RSTN'],
  intPin: ['INT', 'INTN', 'IRQ'],
  wrPin: ['WR', 'LCD_WR'],
  rdPin: ['RD', 'LCD_RD'],
  ...Object.fromEntries(
    // LCD_D0..LCD_D7 as a parallel board prints them.
    Array.from({ length: 8 }, (_, bit) => [`d${bit}Pin`, [`D${bit}`, `LCD_D${bit}`]]),
  ),
  sckPin: ['SCK', 'CLK', 'SCL', 'D0', 'SCLK'],
  mosiPin: ['MOSI', 'SDA', 'DIN', 'DATA', 'D1'],
  misoPin: ['MISO', 'DO'],
  backlightPin: ['BL', 'LED', 'LITE', 'BACKLIGHT'],
  // An I2C OLED is not always silkscreened SDA/SCL: Adafruit's SSD1306 breakout
  // prints the SPI names DATA and CLK on the same two lines it answers I2C on.
  sdaPin: ['SDA', 'SDI', 'DATA', 'DIN', 'D1'],
  sclPin: ['SCL', 'CLK', 'SCK', 'D0'],
  xshutPin: ['SHDN', 'XSHUT'],
  sigPin: ['SIG', 'S', 'SIGNAL'],
  pwmPin: ['PWM'],
  tachPin: ['RPM', 'TACH', 'TACHO'],
  // UART names cross: the controller's RX lands on the module's TX and vice versa.
  uartRxPin: ['TX'],
  uartTxPin: ['RX'],
  busyPin: ['BUSY'],
  // The three I2S MEMS microphones print the same three signals under three
  // sets of names: an INMP441 says WS/SCK/SD, an Adafruit-form ICS-43434 says
  // LRCL/BCLK/DOUT, and the generic MSM261 boards follow the INMP441.
  i2sWs: ['WS', 'LRCL', 'LRCLK', 'LRC'],
  i2sSck: ['SCK', 'BCLK', 'BCK', 'CLK'],
  i2sSd: ['SD', 'DOUT', 'DATA', 'DO'],
  // Grove digital sensors print SIG for their one controller line.
  pin: ['SIG', 'S', 'OUT', 'DAT'],
  // DFRobot prints the digitiser's select and pen interrupt as TOUCH_CS and INT.
  touchCsPin: ['T_CS', 'TOUCH_CS'],
  touchIrqPin: ['T_IRQ', 'INT'],
  touchSckPin: ['T_CLK'],
  touchMosiPin: ['T_DIN'],
  touchMisoPin: ['T_DO'],
  ...Object.fromEntries(
    Array.from({ length: 8 }, (_, index) => [`in${index + 1}Pin`, [`IN${index + 1}`]]),
  ),
}

/**
 * The property holding a MOSFET switch channel's GPIO: `signalPin` for the
 * first channel, as a one-channel board has always named it, then
 * `signal2Pin` and on. Defined here because a board's printed channel letters
 * are those keys' silkscreen labels; `state/peripherals/powerSwitch.ts` builds its
 * channels from it.
 */
export function mosfetChannelPinKey(index: number): string {
  return index === 0 ? 'signalPin' : `signal${index + 1}Pin`
}

/** The exact label printed on a catalogued part for one graph pin property. */
export function partPinLabelForProperty(partId: string, propertyKey: string): string | null {
  const entry = partById(partId)
  const inputs = entry?.mosfet?.channelInputLabels ?? entry?.mosfet?.channelLabels
  const channel = inputs?.findIndex((_, index) => mosfetChannelPinKey(index) === propertyKey) ?? -1
  if (channel >= 0) return inputs![channel]
  // A relay's silkscreen (CTR1, CTR2) is not the left-to-right header order.
  const relayInputs = entry?.relay?.channelInputLabels
  const relayChannel = relayInputs?.findIndex((_, index) => `in${index + 1}Pin` === propertyKey) ?? -1
  if (relayChannel >= 0) return relayInputs![relayChannel]
  const labels = entry?.pinLabelsLeftToRight ?? []
  const aliases = PART_PIN_PROPERTY_ALIASES[propertyKey]
  if (!aliases) return null
  return labels.find((label) => aliases.includes(label.toUpperCase())) ?? null
}

/** The catalogued size, or `fallback` for a part not modelled yet. */
/**
 * Pads a two-board part carries on both boards and joins between them.
 *
 * The MAX98357A stereo pair prints each board's pads with an `L:` or `R:`
 * prefix. The bus, supply and ground are one net across both boards; a
 * board's own SD (which channel it plays) and GAIN are per-board settings and
 * are never bridged. Empty for any part that is a single board.
 */
const PER_BOARD_PADS = new Set(['SD', 'GAIN'])

export function sharedPadsAcrossBoards(partId: string): string[] {
  const pads = partById(partId)?.pinLabelsLeftToRight ?? []
  const left = pads.filter((pad) => pad.startsWith('L:')).map((pad) => pad.slice(2))
  const right = new Set(pads.filter((pad) => pad.startsWith('R:')).map((pad) => pad.slice(2)))
  return left.filter((pad) => right.has(pad) && !PER_BOARD_PADS.has(pad))
}

export function partDimensionsMm(
  partId: string,
  fallback: { width: number; height: number },
): { width: number; height: number } {
  return partById(partId)?.dimensionsMm ?? fallback
}

/**
 * The picture of a downloaded part: an object URL the render store made from
 * bytes it verified against the signed index (hash, WebP, bounds). It belongs
 * to one revision; a different revision of the part has no picture until its
 * own is attached.
 */
const downloadedRenders = new Map<string, { revision: number; url: string }>()

/**
 * Attach (or with `null`, detach) a downloaded part's verified picture. Only a
 * registered downloaded part can hold one. Moves the catalogue version so
 * every view that draws the part draws it again.
 */
export function setDownloadedRender(partId: string, revision: number, url: string | null): boolean {
  if (partOrigin(partId) !== 'downloaded') return false
  const existing = downloadedRenders.get(partId)
  if (url === null) {
    if (!existing) return true
    downloadedRenders.delete(partId)
  } else {
    if (existing?.url === url) return true
    downloadedRenders.set(partId, { revision, url })
  }
  catalogueChanged()
  return true
}

/** Whether a downloaded part already has a picture for the revision registered now. */
export function hasDownloadedRender(partId: string): boolean {
  const have = downloadedRenders.get(partId)
  const revision = (partById(partId) as { revision?: unknown } | undefined)?.revision
  return !!have && have.revision === revision
}

/**
 * Site-root render path for a bundled part, the verified object URL for a
 * downloaded one, or null while a part has no picture (callers draw their
 * placeholder).
 */
export function partRenderSrc(partId: string): string | null {
  if (partOrigin(partId) === 'downloaded') {
    const have = downloadedRenders.get(partId)
    const revision = (partById(partId) as { revision?: unknown } | undefined)?.revision
    return have && have.revision === revision ? have.url : null
  }
  const file = partById(partId)?.render?.file
  return file ? `/${file}` : null
}

/**
 * Whether a catalogued part is an auxiliary display.
 *
 * Derived from the asset declaring a display spec rather than from a category
 * string, so the two cannot drift apart — the same reasoning
 * `isHardwareOnlyNodeType` uses in build/hardware.ts. A part either states its
 * controller and resolution or it is not a display.
 */
export function isDisplayPart(partId: string): boolean {
  return partById(partId)?.display !== undefined
}

/**
 * Whether a catalogued display can report a touch at all.
 *
 * Not the same question as which digitiser it uses. A bare resistive sheet has
 * no controller to name - it is two layers wired across lines the LCD bus
 * already owns - so `touchController` is honestly null on such a panel and
 * every reader that asked only that read it as having no touch. That is one
 * question with one answer, so it lives here rather than being spelled out at
 * each of the ten places that ask it.
 *
 * Two callers deliberately still ask the narrower question: the pin gate, for
 * which an SPI panel needs a digitiser before it has a touch *header* to wire,
 * and the hardware manifest, which records the controller's identity and for
 * which null is the truth.
 */
export function displayHasTouch(partId: string): boolean {
  const display = partById(partId)?.display
  return Boolean(display?.touchController || display?.touchSurface)
}

/** Every catalogued display, in catalogue order. */
export function catalogueDisplays(): PartCatalogueEntry[] {
  return Object.values(PART_CATALOGUE).filter((entry) => entry.display !== undefined)
}

/**
 * Catalogued displays that no part menu offers, and why each is held back.
 *
 * A modelled part is not the same as a drivable one. These have real assets,
 * measured dimensions and measured pad geometry, so they belong in the
 * catalogue - but listing one in a menu would be a claim the firmware cannot
 * keep, because nothing can generate a working sketch for it yet.
 *
 * Stated once because three places ask the question and they had drifted:
 * `displayPartCoverage.test.ts` (a rendered part must be offered or named
 * here), `hardwareRegistries.test.ts` (the same rule from the node side), and
 * `scripts/compile-fixtures/display.ts` (which refuses to build a fixture set
 * that silently omits a part). Naming an id here rather than skipping
 * unoffered parts is what keeps a *newly* unoffered part a failure.
 *
 * Empty since the ILI9341 SPI breakout gained its fixture on 8 October 2026.
 * Name an id with its reason, and remove it the moment a build of that part
 * can light up, not before.
 */
export const CATALOGUE_ONLY_DISPLAY_PART_IDS: readonly string[] = []

/** The panel geometry a fixed layout is computed against. */
export function displayResolution(partId: string): { width: number; height: number } | null {
  const spec = partById(partId)?.display
  if (!spec) return null
  const [width, height] = spec.resolutionPx
  return { width, height }
}

/** Every catalogued ring, smallest first — the counts that were modelled. */
export function catalogueRings(): Array<{ count: number; diameterMm: number }> {
  return Object.values(PART_CATALOGUE)
    .filter((entry) => entry.ledLayout?.form === 'ring' && entry.ledLayout.count)
    .map((entry) => ({
      count: entry.ledLayout!.count!,
      diameterMm: entry.ledLayout!.diameterMm ?? entry.dimensionsMm.width,
    }))
    .sort((a, b) => a.count - b.count)
}

/**
 * How wide a ring of `ledCount` LEDs really is.
 *
 * Measured where the part exists — rings are sold in fixed counts and those are
 * the ones modelled (8, 12, 16, 24, 60) — and interpolated between neighbours
 * otherwise. It is deliberately not a formula: real rings are not linear in LED
 * count, because a small ring needs a minimum hub regardless of how few LEDs
 * sit on it. An 8-LED ring measures 32.2 mm where even pitch would predict 21.6,
 * and the old `N x 10 / pi` was wrong at both ends of the range.
 *
 * Outside the modelled range the nearest ring's pitch is held constant, which
 * is the honest extrapolation: beyond 60 LEDs the hub stops mattering and the
 * circumference is all that grows.
 */
export function ringDiameterMm(ledCount: number): number {
  const rings = catalogueRings()
  const count = Math.max(1, Math.round(ledCount))
  if (rings.length === 0) return Math.max(12, (count * 10) / Math.PI)

  const exact = rings.find((ring) => ring.count === count)
  if (exact) return exact.diameterMm

  const first = rings[0]
  const last = rings[rings.length - 1]
  if (count < first.count) return (first.diameterMm * count) / first.count
  if (count > last.count) return (last.diameterMm * count) / last.count

  for (let i = 0; i < rings.length - 1; i++) {
    const lo = rings[i]
    const hi = rings[i + 1]
    if (count >= lo.count && count <= hi.count) {
      const t = (count - lo.count) / (hi.count - lo.count)
      return lo.diameterMm + (t * (hi.diameterMm - lo.diameterMm))
    }
  }
  return last.diameterMm
}
